import os
import json
import uuid
import threading
from pathlib import Path
from typing import Any, Dict, List, Optional
import builtins
open = builtins.open

class McLogExLogger:
    """mcTassEx 日志记录器，支持多进程离线分析"""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if hasattr(self, '_initialized'):
            return
        self._initialized = True
        self._enabled = os.environ.get('MCTLASS_LOG_ENABLE', '').lower() == 'on'
        self._log_dir = Path(os.environ.get('MCTLASS_LOG_DIR', os.path.expanduser('~/.mctlassex')))
        try:
            self._buf_size = int(os.environ.get('MCTLASS_LOG_BUF_SIZE', '100'))
        except ValueError:
            self._buf_size = 100
        self._buffer: List[Dict] = []
        self._pid = os.getpid()
        self._log_file = None

        if self._enabled:
            self._log_dir.mkdir(parents=True, exist_ok=True)
            unique_id = uuid.uuid4().hex[:8]
            self._log_file = self._log_dir / f"mctlassex_{self._pid}_{unique_id}.log"
            print(f"[mctlassex] Log enabled, output: {self._log_file}")

    def _tensor_info(self, tensor: Any) -> Optional[Dict]:
        """提取张量信息"""
        if tensor is None:
            return None
        if not hasattr(tensor, 'shape') or not hasattr(tensor, 'dtype'):
            return str(tensor)
        return {
            "shape": list(tensor.shape),
            "dtype": str(tensor.dtype).split('.')[-1]
        }

    def _tensor_info_with_values(self, tensor: Any, max_values: int = 100) -> Optional[Dict]:
        """提取张量信息，包含具体值"""
        if tensor is None:
            return None
        if not hasattr(tensor, 'shape') or not hasattr(tensor, 'dtype'):
            return str(tensor)

        # 获取具体值
        try:
            values = tensor.detach().cpu().tolist()
            # 如果值太多，截断
            if isinstance(values, list) and len(values) > max_values:
                values = values[:max_values]
            return {
                "shape": list(tensor.shape),
                "dtype": str(tensor.dtype).split('.')[-1],
                "values": values
            }
        except Exception:
            return {
                "shape": list(tensor.shape),
                "dtype": str(tensor.dtype).split('.')[-1]
            }

    def _serialize_value(self, value: Any) -> Any:
        """序列化参数值"""
        if value is None:
            return None
        if hasattr(value, 'shape'):  # torch.Tensor
            return self._tensor_info(value)
        if isinstance(value, (int, float, str, bool)):
            return value
        if isinstance(value, (list, tuple)):
            return [self._serialize_value(v) for v in value]
        if isinstance(value, dict):
            return {k: self._serialize_value(v) for k, v in value.items()}
        return str(value)

    def log(self, module: str, interface: str, params: Dict, return_value: Any = None):
        """记录日志"""
        if not self._enabled:
            return

        log_entry = {
            "pid": self._pid,
            "module": module,
            "interface": interface,
            "params": {k: self._serialize_value(v) for k, v in params.items()},
            "return": self._serialize_value(return_value),
        }

        self._buffer.append(log_entry)

        # 检查是否需要刷新
        if len(self._buffer) >= self._buf_size:
            self._flush()

    def _flush(self):
        """刷新缓冲区到文件"""
        if not self._buffer or not self._log_file:
            return

        try:
            with open(self._log_file, 'a') as f:
                for entry in self._buffer:
                    f.write(json.dumps(entry) + '\n')
            self._buffer.clear()
        except Exception as e:
            print(f"[mctlassex] Failed to write log: {e}")

    def __del__(self):
        """析构时刷新缓冲区"""
        if hasattr(self, '_buffer') and self._buffer:
            self._flush()


def get_logger() -> McLogExLogger:
    """获取日志器实例"""
    return McLogExLogger()
